var list=new System.Collections.Generic.List<object>();foreach(var n in new[]{"Birch","Poplar","Linden","Maple"}){string f="Assets/Maps/Buildings/Textures/UrbanBark_"+n+"_01";var m=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(f+"/M_UrbanBark_"+n+"_01_URP.mat");foreach(var s in new[]{"_BaseMap","_BumpMap","_ParallaxMap","_OcclusionMap","_MetallicGlossMap"})if(!m.GetTexture(s))throw new Exception(n+s);var ti=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture("_BumpMap")));list.Add(new{tree=n,shaderErrors=UnityEditor.ShaderUtil.ShaderHasError(m.shader),normal=ti.textureType.ToString(),wrap=ti.wrapMode.ToString(),maps=System.IO.Directory.GetFiles(f,"*.png").Length});}return list;
